// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy >= 0);
        uint256 p0;
        try c.pastBlockTime() returns (uint256 __r) { p0 = __r; } catch { return; }
        uint256 p1;
        try c.pastBlockTime() returns (uint256 __r) { p1 = __r; } catch { return; }
        assertTrue(p0 == p1 && p0 <= block.timestamp);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
